export type Choice = "auto" | "none" | { type: "function"; name: string };
export interface Part {
  type: "text";
  text: string;
}
export type Output = Array<Part | { type: "image"; url: string }>;
export interface InputItem {
  type: "out";
  call_id: string;
  output: string | Output;
}
export type Input = Array<InputItem>;
export interface Params {
  model: string;
  tool_choice?: Choice;
  input?: InputItem[];
}
export declare function params(): Params;
export declare function create(p: Params): string;
export declare function keep(v: unknown): void;
export declare function same(v: unknown): boolean;
export declare function ident<T>(v: T): T;
export declare function mutateKept(): void;
export declare function mutateKeptName(): void;
export declare function send(input: Input): string;
